title:
// Target
x = 1                // x는 Target (값 받음)
let y = 2            // y는 Target (값 받음)
for (let i of arr)   // i는 Target (매 루프마다 값 받음)
function foo() {}    // foo는 Target (함수 연결)
foo(73)              // 매개변수도 Target (73이 할당됨)

// Source
console.log(x)       // x는 Source (값 꺼냄)
return x             // x는 Source (값 꺼냄)
if (x == 1)          // x는 Source  컴파일 vs 런타임

