title:
// strict mode 아닐 때
function foo() {
  x = 1  // x 선언 없음, Target
}
foo()
console.log(x)  // 1 출력 (전역에 생성됨 ❌)

// strict mode 일 때
'use strict'
function foo() {
  x = 1  // ReferenceError ❌
}

